F=[]
def add(id,n,k,a,s,c,fly=None,i=None,dist=None,more=None):
    e={"id":id,"n":n,"k":k,"a":a,"s":s,"c":c}
    if fly:e["fly"]=fly
    if i:e["i"]=i
    if dist:e["dist"]=dist
    F.append(e)
def fmt(x,d=0):return f"{x:,.{d}f}"
LY=3.26156
NFS="NASA Planetary Fact Sheet (NSSDCA, D. R. Williams, 2025)"
