    sz=f"{nm} is {fmt(dia,1 if dia<1000 else 0)} km across"+("" if nm=="Earth" else f", about {er:.2f} times Earth's width" if er<1 else f", about {er:.1f} times Earth's width")+"."
    day=p['day'];yr=p['yr']
    dd=f"A day (sunrise to sunrise) on {nm} lasts {fmt(day,1)} hours"+(f" (about {day/24:.0f} Earth days)" if day>48 else "")+"."
    yy=f"A year on {nm} is {fmt(yr,1)} Earth days"+(f" (about {yr/365.25:.1f} Earth years)" if yr>700 else "")+"."
    mo=f"{nm} has {p['moons']} known moon{'s' if p['moons']!=1 else ''} (NASA fact sheet count)." if p['moons'] else f"{nm} has no moons."
    tt=f"The mean temperature on {nm} is about {p['T']} °C."
    ms=f"{nm}'s mass is {p['mass']} × 10^24 kg"+("" if nm=="Earth" else f", about {float(p['mass'])/5.97:.3g} times Earth's")+f". Surface gravity: {p['g']} m/s²"+("" if nm=="Earth" else " (Earth: 9.8)")+"."
