    au=math.sqrt(sum(x*x for x in p['au']));dist=f"On 14 Oct 2026 {nm} is {au:.2f} AU from the Sun ({au*149.6:,.0f} million km; JPL Horizons, as on the map)." if nm!="Earth" else "Earth is about 1 AU (149.6 million km) from the Sun."
    add(nm.lower(),nm,al,a,src,"dwarf" if p.get('dwarf') else "planet","body:"+nm,{"dist":dist,"size":sz+" "+mo,"day":dd,"year":yy,"moons":mo,"temp":tt,"mass":ms,"grav":ms})
