    add(id,n,k,a,"NASA Exoplanet Archive (pscomppars)"+src_extra,"star","star:"+host,{"dist":f"{n} is {ly:,.2f} light-years away ({h['d']:.2f} pc)."},{"map":f"{ly:,.2f} ly"})
