# ---------- exoplanets (map's NASA Exoplanet Archive pscomppars values)
EA="NASA Exoplanet Archive, Planetary Systems Composite Parameters (pscomppars), downloaded 14 Oct 2026 (as used on this map)"
def planet(host,pl,id,k,fun,show_mass=False):
    h=EXO[host];p=[q for q in h['p'] if q[0]==pl][0];ly=h['d']*LY
    r,m,per,teq,yr,meth=p[1],p[2],p[3],p[4],p[5],p[6]
    bits=[]
    if meth=="Transit" and r: bits.append(f"radius {r:.3g} times Earth's")
    if meth=="Radial Velocity" and m: bits.append(f"minimum mass {m:g} Earths" if m<50 else f"minimum mass about {m/317.8:.2g} Jupiters")
    if show_mass and m and meth!="Radial Velocity": bits.append(f"mass {m:.3g} Earths" if m<50 else f"mass about {m/317.8:.2g} Jupiters")
    if per: bits.append(f"one orbit takes {per:,.2f} days" if per<100 else f"one orbit takes {per:,.0f} days")
    if teq: bits.append(f"equilibrium temperature about {teq:,.0f} K ({teq-273:,.0f} °C)")
    a=f"{fun} {pl}: "+"; ".join(bits)+f". Found {yr} by {meth.lower()}. It's {ly:,.0f} light-years away." if ly>=20 else f"{fun} {pl}: "+"; ".join(bits)+f". Found {yr} by {meth.lower()}. It's {ly:,.1f} light-years away."
    add(id,pl,k,a,EA,"exoplanet","star:"+host,{"dist":f"{pl} is {ly:,.1f} light-years away."},{"map":f"{ly:,.1f} ly"})
