add("milkyway","The Milky Way",["milky way","our galaxy","home galaxy","milkyway","you are here","where are we"],"The Milky Way is our home galaxy: a barred spiral about 100,000 light-years across with roughly 100 to 400 billion stars. The Sun is about 26,000 light-years from the centre and takes about 230 million years to go round once.","NASA Science: Milky Way; GRAVITY Collaboration 2019 (8.18 kpc to the centre)","galaxy","mw",{"size":"The Milky Way's disc is about 100,000 light-years across, but only about 1,000 light-years thick: as flat as a CD.","dist":"We're inside the Milky Way, about 26,000 light-years from its centre.","age":"The Milky Way's oldest stars are about 13 billion years old.","stars":"The Milky Way has roughly 100 to 400 billion stars."})
add("galcentre","Galactic centre",["galactic centre","galactic center","centre of the milky way","center of the milky way","middle of the galaxy"],"The centre of the Milky Way is about 26,000 light-years away towards Sagittarius. It hides a black hole, Sagittarius A*, with about 4 million times the Sun's mass.","GRAVITY Collaboration 2019; EHT Collaboration 2022","galaxy","mw")
add("sunorbit","The Sun's orbit",["galactic year","how fast are we moving","speed of the sun","cosmic year"],"The Sun orbits the Milky Way at about 230 km/s (about 830,000 km/h). One lap, a 'galactic year', takes about 230 million years. Last time we were here, the first dinosaurs were just appearing.","NASA Science; Reid et al. 2019, ApJ","galaxy","mw")
add("mwandromeda","Milky Way vs Andromeda",["andromeda collision","milkomeda","will andromeda hit us","galaxy collision","collide"],"Andromeda is heading our way at about 110 km/s. A 2025 study (Sawala et al., Nature Astronomy) found about a 50/50 chance the two galaxies merge within the next 10 billion years. The stars themselves would almost never hit each other.","Sawala et al. 2025, Nature Astronomy; van der Marel et al. 2012","galaxy","gi:Andromeda Galaxy (M31)")
# ---------- galaxies from the map's name index
def gal(name,id,k,fun,std=None,src="",d_override=None,dist_word=None):
    e=GI[name];d=e['d'];ly=d*3.26156e6
    def lys(x):return f"{x/1e9:.2f} billion" if x>=1e9 else f"{x/1e6:.1f} million" if x<1e7 else f"{x/1e6:,.0f} million" if x>=1e6 else f"{x/1e3:,.0f},000".replace(",000,000",",000")
    if ly<1e6: mapd=f"{ly/1e3:,.0f} thousand light-years"
    else: mapd=f"{lys(ly)} light-years"
    how=e['m'] or ""
    mapline=f"The map's name index puts it at {mapd} ({d:g} Mpc, {how})." if d>0 else ""
    a=fun+(f" Standard distance: {std}. " if std else " ")+mapline
    dist={"map":mapd}
    if std: dist["std"]=std
    add(id,e['n'],k,a.strip(),(src+"; " if src else "")+"Map name index (galaxy_index.js: NED/SIMBAD distances, or redshift with Planck 2018)","galaxy" if e['g']!="Galaxy clusters" else "cluster","gi:"+name,{"dist":(f"{e['n']} is {std} away. " if std else "")+mapline},dist)
